TXT=lambda d:(d['t']+' '+' '.join(d['g'])+' '+d['cn']).lower()
LAND=[
('karizma-album-psd','Karizma Album PSD','Karizma Album PSD Free Download – 12x36 Design Sheets (No Password)','12x36',lambda d:'karizma' in TXT(d),'Karizma albums are the premium, photo-printed flush-mount books that Indian studios deliver for weddings and big family events. Their wide 12x36 spreads need layouts that look rich without hiding faces, and that is exactly what this collection of Karizma album PSD sheets is built for.'),
('12x36-wedding-album-psd-free-download','12x36 Wedding Album PSD','12x36 Wedding Album PSD Free Download – Editable Album Sheets','12x36',lambda d:d['c']=='wedding-album-12x36','The 12x36 inch spread is the most common wedding album size in India. Opened flat it gives a panoramic canvas for one hero portrait plus supporting candid frames, which is why most studios design their albums in this format first.'),
('wedding-album-design-psd','Wedding Album Design PSD','Wedding Album Design PSD – Free Layered Templates for Photoshop','12x36, 12x30, 12x18 and 18x24',lambda d:d['c'].startswith(('wedding-album','album-1')),'A good wedding album design PSD saves an album designer hours per book. Instead of building frames, shadows and ornaments from scratch, you start with a balanced layout and spend your time on photo selection and colour.'),
('birthday-album-psd','Birthday Album PSD','Birthday Album PSD Free Download – 12x36 Kids and 1st Birthday Designs','12x36',lambda d:'birthday' in TXT(d) or d['c']=='birthday-baby-album','Birthday albums need a completely different mood from wedding books: brighter colours, playful shapes and room for cake, decorations and family group photos. These birthday album PSD templates are made for first birthdays, kids parties and milestone celebrations.'),
('photoshop-wedding-album-templates','Photoshop Wedding Album Templates','Photoshop Wedding Album Templates – Free PSD Downloads for Studios','12x36, 12x30 and 18x24',lambda d:d['c'] in('wedding-album-12x36','album-12x30','album-18x24'),'Photoshop wedding album templates give you a professional starting point: clipping masks for photos, grouped decorations and editable text. Open a template, drop in your images and the spread is ready for print.'),
('tamil-wedding-album-psd','Tamil Wedding Album PSD','Tamil Wedding Album PSD Free Download – Traditional 12x36 Designs','12x36',lambda d:'tamil-wedding-album-psd' in d['g'],'Tamil weddings are rich in ritual: Nichayathartham, Muhurtham, Oonjal, Saptapadi and the reception all deserve their own spreads. These Tamil wedding album PSD designs use temple motifs, kolam patterns, maroon and gold colour schemes that suit South Indian ceremonies.'),
('kerala-wedding-album-psd','Kerala Wedding Album PSD','Kerala Wedding Album PSD – Elegant 12x36 Designs for Kerala Weddings','12x36',lambda d:d['c']=='wedding-album-12x36' and any(w in TXT(d) for w in('floral','minimal','soft','classic','elegant','lotus')),'Kerala wedding albums usually favour clean, elegant layouts: kasavu whites and golds, soft florals and plenty of breathing space around the couple. This page collects minimal, floral and classic album designs that match that style.'),
('telugu-wedding-album-psd','Telugu Wedding Album PSD','Telugu Wedding Album PSD – Free 12x36 Designs for Telugu Weddings','12x36',lambda d:d['c']=='wedding-album-12x36' and any(w in TXT(d) for w in('royal','golden','grand','ornate','maroon','temple')),'Telugu weddings are colourful and grand, from Pellikoothuru and Mangala Snanam to Jeelakarra Bellam and Talambralu. Royal, golden and ornate album layouts suit these ceremonies best, so this page focuses on those styles.'),
('album-cover-psd','Album Cover PSD','Album Cover PSD Free Download – Wedding Album Cover Designs','12x18 and 12x36',lambda d:d['c']=='album-cover','The cover is the first thing a client sees and touches. These album cover PSD designs combine a strong couple portrait area with clean typography for names and dates.'),
('album-background-psd','Album Background PSD','Album Background PSD Free Download – Wedding and Karizma Backgrounds','12x36',lambda d:d['c']=='album-background','Backgrounds set the colour and mood of every spread. These album background PSD files are high-resolution textures and patterns you can place behind your own frames and photos.'),
('baby-album-psd','Baby Album PSD','Baby Album PSD Free Download – Newborn and Kids Album Designs','12x36',lambda d:'baby-album-psd' in d['g'],'Baby albums capture the first months and years: newborn shoots, naming ceremonies, first steps and first birthdays. These baby album PSD templates use soft colours and gentle shapes that parents love.'),
('muslim-wedding-album-psd','Muslim Wedding Album PSD','Muslim Wedding Album PSD Free Download – Nikah and Walima Designs','12x36',lambda d:'muslim' in TXT(d),'Muslim wedding albums are usually planned around the Nikah, family portraits and the Walima reception. These designs use elegant geometric patterns, arches and soft gold tones.'),
('pre-wedding-album-psd','Pre-Wedding Album PSD','Pre-Wedding Album PSD Free Download – Couple Shoot Album Designs','12x36 and 12x18',lambda d:'pre-wedding-album-psd' in d['g'],'Pre-wedding shoots are more cinematic and personal than ceremony coverage, so their albums need cleaner layouts with bigger photos and less ornament.'),
('engagement-album-psd','Engagement Album PSD','Engagement Album PSD Free Download – Ring Ceremony Album Designs','12x36',lambda d:'engagement' in TXT(d),'Engagement albums focus on the ring exchange, family blessings and the first official photos of the couple together. These layouts give the ring and the couple centre stage.'),
('12x30-album-psd','12x30 Album PSD','12x30 Album PSD Free Download – Wedding and Birthday Album Sheets','12x30',lambda d:'12x30' in TXT(d),'12x30 is a slightly more compact panoramic size that many labs print at a lower cost than 12x36. These 12x30 album PSD sheets are set up at the correct proportions so you do not lose any part of the design.'),
('12x18-album-psd','12x18 Album PSD','12x18 Album PSD Free Download – Compact Album Sheets and Covers','12x18',lambda d:'12x18' in TXT(d),'12x18 albums and covers are popular for smaller packages, pre-wedding books and parent albums. These files are prepared at 12x18 proportions for quick printing.'),
('18x24-album-psd','18x24 Album PSD','18x24 Album PSD Free Download – Large Format Album Designs','18x24',lambda d:'18x24' in TXT(d),'18x24 is a large-format size used for premium coffee-table albums and big portrait spreads. These 18x24 album PSD files keep enough resolution for sharp large prints.'),
('studio-background-psd','Studio Background PSD','Studio Background PSD Free Download – HD Backdrops for Photo Studios','various',lambda d:d['c']=='studio-background','Studio background PSDs let you place portraits on clean, professional backdrops without a physical set. They are ideal for passport studios, portrait sessions and quick event prints.'),
('wedding-invitation-psd','Wedding Invitation PSD','Wedding Invitation PSD Free Download – Editable Save the Date Designs','various',lambda d:d['c']=='wedding-invitation','Wedding invitation and save-the-date PSDs let studios offer matching stationery with their albums. Edit names, dates and venues, then print or share digitally.'),
('dm-album-psd','DM Album PSD','12x36 DM Album PSD Free Download – Ready Album Sheets','12x36',lambda d:d['c']=='wedding-album-12x36' and d['q']>0,'Studios often call ready-made album sheets "DM album PSD" files: complete double-page spreads with frames, ornaments and text already designed. Swap in your photos and the sheet is finished.'),
]
SECS=[
('Why designers choose these {kw} files',['Every file on this page is a layered Photoshop document, not a flattened image. Photos sit inside clipping masks, decorations are grouped, and text layers stay editable, so you can adapt each design to a client in minutes. Unlike many free PSD sites, there is no ZIP password, no login and no signup: open a design, check the specifications, and download it from Google Drive.','Most free {kw} posts online bundle 10 to 30 files behind a password-protected ZIP. Here every design has its own page with a full uncropped preview, exact pixel dimensions, DPI and file size, so you know exactly what you are downloading before you click. There is no password and no login.']),
('Specifications at a glance',['These {kw} designs are prepared for {size} printing. Most files are 200 or 300 DPI in RGB colour, which is what most Indian digital labs expect. Check the dimensions on each design page before you start: a 12x36 spread at 300 DPI is 10800x3600 pixels, while at 150 DPI it is 5400x1800 pixels. Keep faces and names at least half an inch away from the centre fold and the trim edge.']),
('How to edit a {kw} file in Photoshop',['1. Download the ZIP and extract it with your system tool or 7-Zip. 2. Open the PSD in Adobe Photoshop CC. 3. Drag your photo onto the document, place it directly above the frame layer and press Alt+Ctrl+G (Option+Cmd+G on Mac) to clip it. 4. Resize with Ctrl+T, then edit names and dates with the Type tool. 5. Recolour ornaments with Hue/Saturation adjustment layers so the original artwork stays untouched. 6. Save a flattened JPG at full resolution for the lab and keep the PSD for corrections.']),
('Tips for a better {kw} album',['Plan the album in story order before you open Photoshop: preparations, ceremony, portraits, family and celebration. Give each spread one hero photo and two to four supporting images instead of filling every frame. Repeat a small colour palette across the book so pages flow together, and use backgrounds from the same set. Proof every spread at 100% zoom, and double-check the spelling of names and dates; clients notice these first.','Choose layouts that match the photos you actually have. A spread with six small frames looks busy if your best images are wide shots. Keep one consistent font pairing across the album, and use the ornaments sparingly; hiding half the decorations often makes a template look more premium.']),
('Printing and file preparation',['Ask your lab for its preferred format before export. Most labs accept high-quality JPG in sRGB; some prefer TIFF or a specific colour profile. Leave the bleed your lab recommends (usually 0.125 to 0.25 inch), flatten a copy for print and archive the layered PSD so reprints and client changes are easy.']),
('Who these designs are for',['These designs are made for wedding photographers, album designers, photo studios, digital labs and freelancers who design albums for clients. Beginners can learn layout from them, and experienced designers can use them as a quick base and customise the details.']),
]
FAQS=[('Are these {kw} files really free?','Yes. Every {kw} design on PSD Album is free to download. There is no login, no signup and no ZIP password.'),
('What size are the {kw} designs?','They are prepared for {size} printing. The exact pixel dimensions, DPI and file size are listed on each design page.'),
('Which software do I need?','Adobe Photoshop CC is recommended. Any editor that supports layered PSD files can open them, but clipping masks work best in Photoshop.'),
('How do I replace the photos?','Place your photo above the frame layer and press Alt+Ctrl+G (Option+Cmd+G on Mac) to clip it into the mask, then resize it with Ctrl+T.'),
('Can I use these designs for client albums?','Yes, you can use them for personal projects and studio client work. Reselling or re-uploading the PSD files as template packs is not allowed.'),
('Why does Google Drive show a warning?','Large ZIP files cannot be virus-scanned by Google Drive, so it shows a notice. Choose "Download anyway" to continue.')]
LANDSLUGS=set()
def landing_pages():
  for slug,kw,title,size,flt,intro in LAND:
    items=sorted([d for d in out if flt(d)],key=lambda x:(-x['q'],x['id']))
    if len(items)<12: continue
    LANDSLUGS.add(slug)
    rnd=random.Random(slug)
    body=f'<p class="lead">{e(intro)}</p><p>This page brings together <b>{len(items)} free {e(kw.lower())} designs</b>, sorted with the highest-quality previews first. Each design opens on its own page with a full preview, specifications and a direct free download.</p>'
    for h,vs in SECS:
      body+=f'<h2>{e(h.format(kw=kw.lower()))}</h2><p>{e(rnd.choice(vs).format(kw=kw.lower(),size=size))}</p>'
    fq=[(q.format(kw=kw.lower(),size=size),a.format(kw=kw.lower(),size=size)) for q,a in FAQS]
    rel=[x for x in LAND if x[0]!=slug]; rnd.shuffle(rel)
    links=''.join(f'<a href="/{x[0]}/">{e(x[1])}</a>' for x in rel[:10])
    blog=''.join(f'<li><a href="/blog/{s}/">{e(t)}</a></li>' for s,t,_ in rnd.sample(BLOG,5))
    url=f'{SITE}/{slug}/'
    ld=[{"@context":"https://schema.org","@type":"CollectionPage","name":title,"url":url,"about":kw,"numberOfItems":len(items)},
        {"@context":"https://schema.org","@type":"FAQPage","mainEntity":[{"@type":"Question","name":q,"acceptedAnswer":{"@type":"Answer","text":a}} for q,a in fq]},
        crumbs([('Home','/'),(kw,f'/{slug}/')]),
        {"@context":"https://schema.org","@type":"ItemList","itemListElement":[{"@type":"ListItem","position":i+1,"url":f"{SITE}/psd/{d['slug']}/"} for i,d in enumerate(items[:24])]}]
    P(f'/{slug}/',title,f'Download {len(items)} free {kw.lower()} files: layered, print-ready Photoshop designs for {size} albums. No password, no login. Full previews and specs for every design.',
crumbbar([(e(kw),None)])+f'''<div class="main-wrap"><main>{LAY(f'<div class="sec-head"><h1 class="sec-title">{e(kw)} Free Download</h1><span class="results-count">{len(items)} designs</span></div><div class="pm-cat-intro"><p>{len(items)} free, layered {e(kw.lower())} designs · No password · No login</p></div><h2 class="fsp-h2">Best {e(kw)} designs</h2>{GRID(items[:24])}<p class="fsp-hub"><a href="/search/?q={quote(kw.lower().replace(' psd',''))}">See all {len(items)} {e(kw)} designs →</a></p><article class="fsp-art lp">'+body+'<h2>Frequently asked questions</h2><div class="fsp-faq">'+''.join(f'<details><summary>{e(q)}</summary><p>{e(a)}</p></details>' for q,a in fq)+f'</div><h2>Related collections</h2><div class="fsp-chips">{links}</div><h2>Helpful guides</h2><ul>{blog}</ul></article>')}</main></div>''',ld=ld,img=items[0]['img'])
